"""Exact unselected lane-control fixture. Native acquisition still requires review."""
import argparse
import json
import xml.etree.ElementTree as ET
from pathlib import Path
from signal_source import map_inventory

ASSIGNMENT = 'training__C230247__NRS-484B-307-12b__motor_vehicle_driver'
CAMERAS = ('overview','approach','reference_corner','driver_reference')
HERE = Path(__file__).resolve().parent
CASE_LANES = {
    ASSIGNMENT+'__probe_1':-2,
    ASSIGNMENT+'__probe_2':-1,
}


def request(frame, case_id):
    if type(frame) is not int or not 0 <= frame < 600:
        raise ValueError('frame outside 600-frame contract')
    if case_id not in CASE_LANES:
        raise ValueError('unknown exact case')
    lane = CASE_LANES[case_id]
    return {'frame':frame,'target_lane_id':lane,'start_lane_id':-2,
            'target_speed_mps':2.5,
            'lateral_speed_mps':0.7 if lane==-1 and 200<=frame<300 else 0.0,
            'signal_id':100,'governing_signal_lane_id':-1,
            'signal_indication_request':'red_x'}


def source_row(index, native_frame, elapsed_s, actor, signal_state, signal_inventory, waypoint, proposed_lane_id):
    if type(index) is not int or not 0 <= index < 600 or type(native_frame) is not int:
        raise ValueError('original frame identity required')
    if actor is None or signal_state is None or signal_inventory is None or waypoint is None:
        raise ValueError('post-tick Native source packets required')
    if signal_inventory.get('authority_source') != 'map_signal_inventory' or not signal_inventory.get('inventory_verified'):
        raise ValueError('original map signal inventory verification required')
    if signal_inventory.get('mount_source') != 'map_signal_transform':
        raise ValueError('signal mount must come from the Native map')
    if signal_state.get('source') != 'native_signal_state' or signal_state.get('signal_id') != signal_inventory.get('id'):
        raise ValueError('original indication state does not join the governed signal')
    if proposed_lane_id not in (-1,-2):
        raise ValueError('proposed lane absent')
    pose=actor.get_transform()
    vertices=actor.bounding_box.get_world_vertices(pose)
    if len(vertices)!=8:
        raise ValueError('actor body vertices missing')
    return {'frame':index,'native_frame':native_frame,'time_s':elapsed_s,
            'source':'native_post_tick',
            'vehicle':{'source':'native_actor_pose','lane_source':'map_waypoint_projection',
                       'actor_id':actor.id,'actor_blueprint':actor.type_id,
                       'yaw_deg':pose.rotation.yaw,'body_vertices_m':[[v.x,v.y,v.z] for v in vertices],
                       'lane_id':waypoint.lane_id,'proposed_lane_id':proposed_lane_id},
            'signal':{'id':signal_inventory['id'],'source':'native_signal_state',
                      'authority_source':'map_signal_inventory','inventory_verified':True,
                      'official_authority_review_pending':True,
                      'mount_source':'map_signal_transform','mount_m':signal_inventory['mount_m'],
                      'lane_id':signal_inventory['lane_id'],'mount_lane_id':signal_inventory['mount_lane_id'],
                      'indication':signal_state['indication'],
                      'facing_yaw_deg':signal_inventory['facing_yaw_deg']}}


def check(config):
    if (config.get('law_id'),config.get('cell_id'),config.get('actor')) != ('NRS-484B-307-12b','C230247','motor_vehicle_driver'):
        raise ValueError('frozen identity differs')
    cid=config.get('case_id')
    if cid not in CASE_LANES:
        raise ValueError('case identity differs')
    if config.get('rate_hz')!=20 or config.get('duration_s')!=30:
        raise ValueError('30-second timing differs')
    if tuple(c['name'] for c in config.get('cameras',[]))!=CAMERAS:
        raise ValueError('four-camera profile differs')
    root=ET.parse(HERE/'road.xodr').getroot()
    inventory=map_inventory((HERE/'road.xodr').read_text())
    lanes=[root.find(f".//lane[@id='{i}']") for i in (-1,-2)]
    if any(l is None or l.get('type')!='driving' or float(l.find('width').get('a'))!=3.5 for l in lanes):
        raise ValueError('two driving lanes absent')
    signal=root.find(".//signal[@id='100']")
    if signal is None or signal.get('dynamic')!='yes' or signal.find('validity').attrib != {'fromLane':'-1','toLane':'-1'}:
        raise ValueError('governing overhead signal absent')
    if float(signal.get('zOffset'))<4.0:
        raise ValueError('overhead mount absent')
    if inventory['id'] != 100 or inventory['lane_id'] != -1:
        raise ValueError('map signal inventory differs')
    req=request(300,cid)
    if req['target_lane_id']!=CASE_LANES[cid]:
        raise ValueError('controlled comparison differs')
    return {'passed':True,'case_id':cid,'frames':600,'rate_hz':20,'cameras':list(CAMERAS),
            'signal_id':100,'signal_valid_lane_id':-1,'target_lane_id':req['target_lane_id'],
            'native_capture_implemented':True,
            'physical_observation_claimed':False}

if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    if not args.check:
        raise SystemExit('Native CARLA orchestration remains unfinished')
    print(json.dumps(check(json.loads((HERE/'config.json').read_text())),sort_keys=True))

"""Fail-closed Native lane-control signal inventory and state acquisition.

A generic traffic-light Green state is not a downward green arrow. This module
requires an exact lane-control asset identity from the original world and keeps
physical pixels and official authority for independent local review.
"""
import hashlib
import math
import xml.etree.ElementTree as ET

SIGNAL_ID = 100


def _number(value, name):
    try:
        number = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError('Missing original ' + name) from exc
    if not math.isfinite(number):
        raise ValueError('Nonfinite original ' + name)
    return number


def map_inventory(native_opendrive):
    if not isinstance(native_opendrive, str) or not native_opendrive:
        raise ValueError('Native OpenDRIVE readback required')
    root = ET.fromstring(native_opendrive)
    roads = [road for road in root.findall('road') if road.get('id') == '1']
    if len(roads) != 1:
        raise ValueError('Original road identity differs')
    signal = next((s for s in roads[0].findall('signals/signal')
                   if s.get('id') == str(SIGNAL_ID)), None)
    if signal is None or signal.get('dynamic') != 'yes':
        raise ValueError('Original dynamic overhead signal absent')
    validity = signal.find('validity')
    if validity is None or validity.attrib != {'fromLane':'-1','toLane':'-1'}:
        raise ValueError('Original governed lane differs')
    if signal.get('orientation') != '+':
        raise ValueError('Original signal orientation differs')
    x = _number(signal.get('s'), 'signal longitudinal position')
    y = _number(signal.get('t'), 'signal lateral position')
    z = _number(signal.get('zOffset'), 'signal mount height')
    if not 0 < x < _number(roads[0].get('length'), 'road length') or not -3.5 < y < 0 or z < 4:
        raise ValueError('Original signal is not overhead of its governed lane')
    return {'id':SIGNAL_ID,'lane_id':-1,'mount_lane_id':-1,
            'mount_m':[x,y,z],'facing_yaw_deg':0.0,
            'authority_source':'map_signal_inventory','inventory_verified':True,
            'mount_source':'map_signal_transform',
            'opendrive_sha256':hashlib.sha256(native_opendrive.encode()).hexdigest(),
            'official_authority_review_pending':True}


def observed_state(native_actor, inventory):
    """Read the native arrow role and live state; never translate plain Green."""
    if inventory.get('id') != SIGNAL_ID or not inventory.get('opendrive_sha256'):
        raise ValueError('Map signal inventory missing')
    if native_actor is None or getattr(native_actor, 'type_id', None) != 'traffic.lane_control_signal':
        raise ValueError('Exact Native lane-control actor absent')
    attributes = getattr(native_actor, 'attributes', None)
    if not isinstance(attributes, dict) or attributes.get('opendrive_signal_id') != str(SIGNAL_ID):
        raise ValueError('Native actor is not bound to original map signal')
    if attributes.get('display_role') != 'red_x':
        raise ValueError('Native asset is not a red-X display')
    if not hasattr(native_actor, 'get_state'):
        raise ValueError('Live Native indication readback absent')
    state = str(native_actor.get_state())
    if state not in ('green_down_arrow', 'red_x', 'dark'):
        raise ValueError('Unsupported or generic Native light state')
    return {'source':'native_signal_state','signal_id':SIGNAL_ID,
            'indication':state,'actor_id':native_actor.id,
            'asset_role_source':'native_actor_attributes',
            'official_authority_review_pending':True}

"""Source-bound engineering measurements for the individual-lane red X.

Lane intersection and motion are observations; this module issues no legal verdict.
"""
import math

ASSIGNMENT = 'training__C230247__NRS-484B-307-12b__motor_vehicle_driver'

def measure(packet):
    rows = packet['frames']
    if len(rows) != 600:
        raise ValueError('expected 600 source frames')
    observations = []
    first_native = None
    first_time = None
    for index, row in enumerate(rows):
        frame = row.get('native_frame')
        time_s = row.get('time_s')
        if type(frame) is not int or type(row.get('frame')) is not int or row['frame'] != index:
            raise ValueError('original frame identity absent')
        if first_native is None:
            first_native = frame
            first_time = time_s
        if frame != first_native + index or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
            raise ValueError('original frame identity discontinuity')
        if abs((time_s - first_time) - index / 20) > .001:
            raise ValueError('source clock discontinuity')
        if row.get('source') != 'native_post_tick':
            raise ValueError('source frame provenance absent')
        signal = row.get('signal')
        vehicle = row.get('vehicle')
        if not isinstance(signal, dict) or not isinstance(vehicle, dict):
            raise ValueError('signal and vehicle source packets required')
        if signal.get('source') != 'native_signal_state' or signal.get('authority_source') != 'map_signal_inventory':
            raise ValueError('original signal provenance absent')
        if signal.get('id') != 100 or signal.get('lane_id') != -1 or signal.get('mount_lane_id') != -1:
            raise ValueError('original governed lane differs')
        if signal.get('mount_source') != 'map_signal_transform' or signal.get('inventory_verified') is not True:
            raise ValueError('overhead map signal source absent')
        if signal.get('official_authority_review_pending') is not True or signal.get('indication') != 'red_x':
            raise ValueError('original red-X state or review status absent')
        mount = signal.get('mount_m')
        if not isinstance(mount, list) or len(mount) != 3 or not all(isinstance(v, (int, float)) and math.isfinite(v) for v in mount):
            raise ValueError('original signal mount absent')
        if not (0 < mount[0] < 120 and -3.5 < mount[1] < 0 and mount[2] >= 4):
            raise ValueError('signal not mounted over governed lane')
        if vehicle.get('source') != 'native_actor_pose' or vehicle.get('lane_source') != 'map_waypoint_projection':
            raise ValueError('original actor body provenance absent')
        vertices = vehicle.get('body_vertices_m')
        if not isinstance(vertices, list) or len(vertices) != 8 or any(
            not isinstance(v, list) or len(v) != 3 or not all(isinstance(n, (int, float)) and math.isfinite(n) for n in v)
            for v in vertices):
            raise ValueError('original actor body vertices absent')
        if vehicle.get('lane_id') not in (-1, -2) or vehicle.get('proposed_lane_id') not in (-1, -2):
            raise ValueError('original actor lane projection absent')
        yaw = vehicle.get('yaw_deg')
        facing = signal.get('facing_yaw_deg')
        if not isinstance(yaw, (int, float)) or not isinstance(facing, (int, float)):
            raise ValueError('driver and signal orientation absent')
        difference = abs((yaw - facing + 180) % 360 - 180)
        y_min = min(v[1] for v in vertices)
        y_max = max(v[1] for v in vertices)
        overlap = y_max > -3.5 and y_min < 0
        wholly_inside = y_min >= -3.5 and y_max <= 0
        observations.append({
            'frame': index, 'native_frame': frame, 'time_s': time_s,
            'signal_id': signal['id'], 'signal_lane_id': -1,
            'red_x': True, 'facing_signal': difference <= 30,
            'vehicle_lane_id': vehicle['lane_id'],
            'governed_lane_overlap': overlap, 'wholly_in_governed_lane': wholly_inside,
            'body_y_range_m': [y_min, y_max]
        })
    first_overlap = next((o['frame'] for o in observations if o['governed_lane_overlap']), None)
    return {
        'format': 'red-x-source-meter-v1', 'assignment_id': ASSIGNMENT,
        'frames': 600, 'rate_hz': 20,
        'red_x_facing_frames': sum(o['red_x'] and o['facing_signal'] for o in observations),
        'governed_lane_overlap_frames': sum(o['governed_lane_overlap'] for o in observations),
        'governed_lane_wholly_inside_frames': sum(o['wholly_in_governed_lane'] for o in observations),
        'first_governed_lane_overlap_frame': first_overlap,
        'observations': observations, 'physical_observation_claimed': False,
        'legal_conclusion': None
    }
